void candidate_forcing_actual_nonbest_direction() {
  const wide::Layout layout{1, 1, 1};
  const std::vector<double> rhs{10, 10, 10, 0, 0};
  for (bool improved : {false, true}) {
    auto target = rhs;
    target[0] = 10.5;
