        work.initial_forcing->defect_norms && (*work.initial_forcing->defect_norms)[0] == 1,
        "真实循环移位算子保3乘32及原窗口末真验，不为gate增加P/A或检查时点");
  }
  for (bool fail_later_true : {false, true}) {
    const wide::Layout layout{1, 1, 1};
